/**
 * OdinTemplateDetail is the preview drawer's payload: the picker's card plus
 * everything the read-through cache already holds for one OE — infobox
 * facts, a PMESII-PT article outline, the section-outline tree, and an
 * honest preview of what the (separate, story-4) faction generator would do
 * with this OE. Every field here comes from data the refresh worker already
 * fetches; Get makes zero upstream ODIN calls.
 *
 * Field numbering: hot band 1-15, cold band 16+. Field 14 is deliberately
 * left free — reserved in spirit, not in the proto, for a future `overview`
 * prose field once the refresh worker fetches article bodies (it does not
 * today: `odin_operational_environment.plaintext` is a hard-coded SQL NULL
 * literal). Field 15 is also unused; the hot band is 1-15.
 *
 * @generated from message omnicore.range.odin_template.v1.OdinTemplateDetail
 */
export type OdinTemplateDetail = Message<"omnicore.range.odin_template.v1.OdinTemplateDetail"> & {
  /**
   * card embeds the exact same OdinTemplate the picker already rendered, so
   * the drawer header IS the card and the MFE reuses its existing parser
   * rather than re-deriving name/region/article_count/updated_at.
   *
   * @generated from field: omnicore.range.odin_template.v1.OdinTemplate card = 1;
   */
  card?: OdinTemplate | undefined;

  /**
   * official_name is the infobox envelope's own `title` (e.g. "People's
   * Republic of Olvana") — the official long-form name, distinct from
   * OdinTemplate.name. Empty when the cached infobox has no title.
   *
   * @generated from field: string official_name = 2;
   */
  officialName: string;

  /**
   * capital, government and population are extracted from the infobox by
   * key/position matching (see extract_infobox_facts); empty when absent or
   * unmatched. No value scrubbing is applied even to incoherent upstream
   * data (e.g. a self-referential ethnic-groups entry) — filtering one bad
   * row risks silently dropping a legitimate one. The drawer instead
   * attributes the section to ODIN.
   *
   * @generated from field: string capital = 3;
   */
  capital: string;

  /**
   * @generated from field: string government = 4;
   */
  government: string;

  /**
   * population is a STRING, not a numeric type: upstream values are
   * locale-formatted human strings (e.g. "8,372,373"), and parsing them
   * into a number would be a second, unverified heuristic layered on top of
   * the extraction heuristic already needed to find the value at all.
   *
   * @generated from field: string population = 5;
   */
  population: string;

  /**
   * @generated from field: repeated string official_languages = 6;
   */
  officialLanguages: string[];

  /**
   * @generated from field: repeated string ethnic_groups = 7;
   */
  ethnicGroups: string[];

  /**
   * pmesii_groups always carries all 8 PMESII-PT sections in canonical
   * order, even when a section has zero articles (~20 of 53 OEs have no
   * articles at all) — the drawer needs the full skeleton to render "no
   * articles cached" per section rather than omitting the section.
   *
   * @generated from field: repeated omnicore.range.odin_template.v1.OdinPmesiiGroup pmesii_groups = 8;
   */
  pmesiiGroups: OdinPmesiiGroup[];

  /**
   * toc is the OE's cached section-outline tree (depth-capped defensively
   * at 4 by the server; no real cached toc exceeds 3). It is a page outline,
   * never an article list — some OEs (Cyber and the functional areas) have
   * a 60+ node toc with zero backing articles.
   *
   * @generated from field: repeated omnicore.range.odin_template.v1.OdinTocNode toc = 9;
   */
  toc: OdinTocNode[];

  /**
