   * the OE's infobox is NULL (~18 of 53 OEs, entirely Cyber and the
   * functional areas).
   *
   * @generated from field: repeated omnicore.range.odin_template.v1.OdinInfoboxProperty infobox = 10;
   */
  infobox: OdinInfoboxProperty[];

  /**
