/**
 * GenerationPreview is an honest preview of what the (separate, story-4,
 * #1724) faction generator would do with this OE — not a sample of its
 * output. The generator is a temperature-0.8 LLM call with a per-run nonce
 * that deliberately varies output between runs (AC2 of #1466), and Range
 * has no equipment concept anywhere in this codebase, so neither "sample
 * factions" nor "sample equipment" can be shown honestly here. This message
 * carries only what is actually knowable ahead of a run: the archetype
 * vocabulary the generator's system prompt seeds it with, the count bounds
 * the validator enforces, and whether output is deterministic (it is not).
 *
 * @generated from message omnicore.range.odin_template.v1.GenerationPreview
 */
export type GenerationPreview = Message<"omnicore.range.odin_template.v1.GenerationPreview"> & {
  /**
   * faction_archetypes lists the 8 archetypes seeded in the faction
   * generator's system prompt (see FactionArchetype below) — inspiration
   * the model is given, not a guarantee of what any run produces.
   *
   * @generated from field: repeated omnicore.range.odin_template.v1.FactionArchetype faction_archetypes = 1;
   */
  factionArchetypes: FactionArchetype[];

  /**
   * default_faction_count and max_faction_count mirror the generator's own
   * requested-count default and its validator's COUNT_CAP — imported from
   * the faction-discovery module by the handler, never re-declared as a
   * literal, so a change to either stays in sync automatically.
   *
   * @generated from field: int32 default_faction_count = 2;
   */
  defaultFactionCount: number;

  /**
   * @generated from field: int32 max_faction_count = 3;
   */
  maxFactionCount: number;

  /**
   * equipment_attach_available is false today and MUST stay false until
   * #1725 (equipment attach, story 5) actually ships — this field exists so
   * the drawer can say so honestly rather than silently omitting the topic.
   *
   * @generated from field: bool equipment_attach_available = 4;
   */
  equipmentAttachAvailable: boolean;

  /**
   * deterministic is false: the generator's temperature-0.8 sampling and
   * per-run nonce mean two runs against the same OE can produce different
   * candidates. Surfaced so the drawer can say "results vary between runs"
   * instead of implying a preview is a promise.
   *
   * @generated from field: bool deterministic = 5;
   */
  deterministic: boolean;
};

/**
 * Describes the message omnicore.range.odin_template.v1.GenerationPreview.
 * Use `create(GenerationPreviewSchema)` to create a new message.
 */
