  messageDesc(file_omnicore_range_odin_template_v1_odin_template, 10);

/**
 * RefreshRequest carries no fields today: the on-demand refresh (Task 11,
 * #1721) always walks the entire ODIN catalog, the same way the periodic
 * background loop does — there is no per-OE or per-region scoping to ask
 * for. An empty message (rather than `google.protobuf.Empty`) keeps this
 * RPC free to grow a scoped variant later without a breaking wire change.
 *
 * @generated from message omnicore.range.odin_template.v1.RefreshRequest
 */
export type RefreshRequest = Message<"omnicore.range.odin_template.v1.RefreshRequest"> & {
};

